entries[78843] = { ["name"] = "Time Lord's Mantle", ["text"] = "Twilight\nBinds when picked up\nShoulder Cloth\n1077 Armor\n+480 Stamina\n+280 Intellect\n+ 165 Critical Strike\n+ 203 Mastery\n\nRed Socket\nRed Socket\nSocket Bonus: + 20 Intellect\n\nDurability 100 / 100\nClasses: Mage\nRequires Level 85\n\nTime Lord's Regalia (0/5)\nTime Lord's Gloves\nTime Lord's Hood\nTime Lord's Leggings\nTime Lord's Robes\nTime Lord's Mantle\n(2) Set : Your Arcane Blast has a 100% chance and your Fireball, Pyroblast, Frostfire Bolt, and Frostbolt spells have a 50% chance to grant Stolen Time, increasing your haste by 50 for 30 sec and stacking up to 10 times. When Arcane Power, Combustion, or Icy Veins expires, all stacks of Stolen Time are lost.\n(4) Set : Each stack of Stolen Time also reduces the base cooldown of Arcane Power, Combustion, and Icy Veins by 5%.\nSell Price:" }
entries[78844] = { ["name"] = "Mantle of the Faceless Shroud", ["text"] = "Twilight\nBinds when picked up\nShoulder Cloth\n1077 Armor\n+480 Stamina\n+280 Intellect\n+ 165 Critical Strike\n+ 203 Mastery\n\nRed Socket\nRed Socket\nSocket Bonus: + 20 Intellect\n\nDurability 100 / 100\nClasses: Warlock\nRequires Level 85\n\nVestments of the Faceless Shroud (0/5)\nGloves of the Faceless Shroud\nHood of the Faceless Shroud\nLeggings of the Faceless Shroud\nRobes of the Faceless Shroud\nMantle of the Faceless Shroud\n(2) Set : The duration of your Doomguard and Infernal summons is increased by [ Summon Felguard : 20 sec / 30 sec] and the cooldown of those spells is reduced by 4 min.\n(4) Set : Increases the damage done by your Agony, Corruption, Incinerate, and Shadow Bolt spells by 5%.\nSell Price:" }
entries[78845] = { ["name"] = "Mantle of Dying Light", ["text"] = "Twilight\nBinds when picked up\nShoulder Cloth\n1077 Armor\n+480 Stamina\n+280 Intellect\n+ 165 Critical Strike\n+ 203 Mastery\n\nRed Socket\nRed Socket\nSocket Bonus: + 20 Intellect\n\nDurability 100 / 100\nClasses: Priest\nRequires Level 85\n\nRegalia of Dying Light (0/5)\nGloves of Dying Light\nHood of Dying Light\nLeggings of Dying Light\nRobes of Dying Light\nMantle of Dying Light\n(2) Set : Shadow Word: Death deals an additional 55% damage, and reduces the damage you take from your own Shadow Word: Death when the target fails to die by 95%.\n(4) Set : Increases the damage done by your Shadow Word: Pain by 15%.\nSell Price:" }
entries[78846] = { ["name"] = "Necrotic Boneplate Shoulderguards", ["text"] = "Twilight\nBinds when picked up\nShoulder Plate\n2764 Armor\n+203 Strength\n+480 Stamina\n+ 132 Expertise\n+ 310 Mastery\n\nYellow Socket\nBlue Socket\nSocket Bonus: + 20 Mastery\n\nDurability 100 / 100\nClasses: Death Knight\nRequires Level 85\n\nNecrotic Boneplate Armor (0/5)\nNecrotic Boneplate Chestguard\nNecrotic Boneplate Handguards\nNecrotic Boneplate Faceguard\nNecrotic Boneplate Legguards\nNecrotic Boneplate Shoulderguards\n(2) Set : When an attack drops your health below 35%, one of your Blood Runes will immediately activate and convert into a Death Rune for the next 20 sec. This effect cannot occur more than once every 45 sec. (45s cooldown)\n(4) Set : Your Vampiric Blood ability also affects all party and raid members for 50% of the effect it has on you.\nSell Price:" }
