entries[79513] = { ["name"] = "Glyph of Mind Flay", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Mind Flay spell no longer slows your victim's movement speed. Instead, each time Mind Flay deals damage you will be granted 15% increased movement speed for 5 sec, stacking up to 3 times.\nSell Price:" }
entries[79514] = { ["name"] = "Glyph of Shadow Word: Death", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Shadow Word: Death can now be cast at any time, but deals 25% damage against targets above 20% health [ Mind Flay : and does not generate a Shadow Orb when used against them ].\n\nCasting Shadow Word: Death now also does damage to you equivalent to the damage it would do to an enemy above 20% health.\nSell Price:" }
entries[79515] = { ["name"] = "Glyph of Vampiric Embrace", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Vampiric Embrace converts an additional 50% of the damage you deal into healing, but the duration is reduced by 5 sec.\nSell Price:" }
entries[79538] = { ["name"] = "Glyph of the Heavens", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Levitate targets will appear to be riding on a cloud for the duration of the spell." }
